import json
import composio
from composio import Composio, schema_modifier, Tool

@schema_modifier(tools=["HACKERNEWS_GET_LATEST_POSTS"])
def modify_hackernews_schema(schema):
    if "properties" in schema.input_parameters and "page" in schema.input_parameters["properties"]:
        schema.input_parameters["properties"].pop("page")

    if "required" not in schema.input_parameters:
        schema.input_parameters["required"] = []

    if "size" not in schema.input_parameters["required"]:
        schema.input_parameters["required"].append("size")

    return schema

def main():
    tools = composio.tools.get(
        user_id="default",
        tools=["HACKERNEWS_GET_LATEST_POSTS"],
        modifiers=[modify_hackernews_schema]
    )

    tool = tools[0]

    schema_dict = {}
    if hasattr(tool, "model_dump"):
        schema_dict = tool.model_dump()
    elif hasattr(tool, "dict"):
        schema_dict = tool.dict()
    elif hasattr(tool, "schema"):
        schema_dict = tool.schema
    else:
        schema_dict = tool.__dict__

    with open("modified_schema.json", "w") as f:
        json.dump(schema_dict, f, indent=4, default=lambda o: o.__dict__)

if __name__ == "__main__":
    main()

